const input = $input.first().json;
const query = input.query ?? input;
const esc = (v) => String(v).replace(/'/g, "''");

const rawCalendarId = query.calendar_source_id != null ? String(query.calendar_source_id).trim() : '';
let calendarSourceIdSql = 'NULL';
if (rawCalendarId !== '') {
  const parsed = parseInt(rawCalendarId, 10);
  if (Number.isNaN(parsed)) throw new Error(`calendar_source_id inválido: ${query.calendar_source_id}`);
  calendarSourceIdSql = String(parsed);
}

const rawUserId = query.user_id != null ? String(query.user_id).trim() : '';
const userIdSql = rawUserId !== '' ? `'${esc(rawUserId)}'` : 'NULL';

return [{ json: { calendar_source_id_sql: calendarSourceIdSql, user_id_sql: userIdSql } }];
